import React, { useState } from 'react';
import axios from 'axios';
import './Prediction.css';

function Prediction() {
  const [formData, setFormData] = useState({
    age: 30,
    gender: 'Female',
    bmi: 25,
    hbA1c_level: 5.7,
    blood_glucose_level: 100,
    hypertension: 0,
    heart_disease: 0,
    smoking_history: 'never'
  });
  const [prediction, setPrediction] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? (checked ? 1 : 0) : value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');
    
    try {
      const response = await axios.post('http://localhost:8000/predict', {
        ...formData,
        year: new Date().getFullYear(),
        location: 'Urban',
        race: 'Caucasian' // Remove if not needed
      });
      setPrediction(response.data);
    } catch (err) {
      setError('Prediction failed. Please try again.');
      console.error('Prediction error:', err);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="prediction-container">
      <h2>Diabetes Risk Prediction</h2>
      
      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <label>Age:</label>
          <input
            type="number"
            name="age"
            value={formData.age}
            onChange={handleChange}
            min="0"
            max="120"
            required
          />
        </div>

        <div className="form-group">
          <label>Gender:</label>
          <select
            name="gender"
            value={formData.gender}
            onChange={handleChange}
            required
          >
            <option value="Female">Female</option>
            <option value="Male">Male</option>
          </select>
        </div>

        <div className="form-group">
          <label>BMI:</label>
          <input
            type="number"
            name="bmi"
            value={formData.bmi}
            onChange={handleChange}
            step="0.1"
            min="10"
            max="50"
            required
          />
        </div>

        <div className="form-group">
          <label>HbA1c Level (%):</label>
          <input
            type="number"
            name="hbA1c_level"
            value={formData.hbA1c_level}
            onChange={handleChange}
            step="0.1"
            min="3"
            max="15"
            required
          />
        </div>

        <div className="form-group">
          <label>Blood Glucose Level (mg/dL):</label>
          <input
            type="number"
            name="blood_glucose_level"
            value={formData.blood_glucose_level}
            onChange={handleChange}
            min="50"
            max="300"
            required
          />
        </div>

        <div className="form-group checkbox">
          <label>
            <input
              type="checkbox"
              name="hypertension"
              checked={formData.hypertension === 1}
              onChange={handleChange}
            />
            Hypertension
          </label>
        </div>

        <div className="form-group checkbox">
          <label>
            <input
              type="checkbox"
              name="heart_disease"
              checked={formData.heart_disease === 1}
              onChange={handleChange}
            />
            Heart Disease
          </label>
        </div>

        <div className="form-group">
          <label>Smoking History:</label>
          <select
            name="smoking_history"
            value={formData.smoking_history}
            onChange={handleChange}
            required
          >
            <option value="never">Never</option>
            <option value="former">Former</option>
            <option value="current">Current</option>
          </select>
        </div>

        <button type="submit" disabled={isLoading}>
          {isLoading ? 'Predicting...' : 'Predict Diabetes Risk'}
        </button>
      </form>

      {error && <div className="error">{error}</div>}

      {prediction && (
        <div className={`result ${prediction.prediction ? 'high-risk' : 'low-risk'}`}>
          <h3>Prediction Result</h3>
          <p>Risk: {prediction.interpretation}</p>
          <p>Probability: {(prediction.probability * 100).toFixed(1)}%</p>
        </div>
      )}
    </div>
  );
}

export default Prediction;
